// === Tab: mySketch ===
// This version uses vector objects to represent particle position and velocity.

let particles;

function setup() {
	createCanvas(windowWidth, windowHeight);
	particles = createParticles(100);
}

function draw() {
	background(100);
	drawConnectingLines();
	drawAllParticles();
	moveAllParticles();
}

function createParticles(numParticles) {
	let newParticles = [];
	for (let i = 0; i < numParticles; i++) {
		let particle = createOneParticle();
		newParticles.push(particle);
	}
	return newParticles;
}

function createOneParticle() {
	var particle = {
		pos: randomScreenPos(),
		vel: randomVelocity(0.09, 2)
	};
	return particle;
}

function drawAllParticles() {
	for (let particle of particles) {
		drawOneParticle(particle);
	}
}

function drawOneParticle(particle) {
	noFill();
	circle(particle.pos.x, particle.pos.y, 10);
}

// Draw connecting lines between particles which are near to each other
function drawConnectingLines() {

	// Known issue (simplification)
	// Double-draw: this will draw a line from A to B AND a line from B to A!

	for (let mainParticle of particles) {
		for (let otherParticle of particles) {
			const thresholdDistance = 80;

			// Don't connect one particle to itself!
			if (mainParticle === otherParticle){
				continue;
			}

			// If nearby, draw a connecting line.
			if (mainParticle.pos.dist(otherParticle.pos) < thresholdDistance) {
				const [p1, p2] = [mainParticle.pos, otherParticle.pos];
				stroke('white')
				line(p1.x, p1.y, p2.x, p2.y);
			}
		}
	}
}

function moveAllParticles() {
	for (let particle of particles) {
		moveOneParticle(particle);
	}
}

function moveOneParticle(particle) {
	particle.pos.add(particle.vel);
	if (particle.pos.x < 0) {
		particle.pos.x += width;
	}
	if (particle.pos.x > width) {
		particle.pos.x -= width;
	}
	if (particle.pos.y > height) {
		particle.pos.y -= height;
	}
	if (particle.pos.y < 0) {
		particle.pos.y -= height;
	}
}

function randomScreenPos() {
	return createVector(random(width), random(height));
}

function randomVelocity(minSpeed, maxSpeed) {
	return p5.Vector.random2D().mult(random(minSpeed, maxSpeed));
}

